def transform(grid):
    n = len(grid) // 3
    out = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            colors = [grid[r][c] for r in range(3*i, 3*i+3) for c in range(3*j, 3*j+3) if grid[r][c] not in (0, 5)]
            if colors:
                out[i][j] = max(set(colors), key=colors.count)
    return out
